impl Mirror for itPickup {
    const SIZE: u32 = 0x30;

    fn import(m: &Mem, at: u32, cx: &mut dyn Cx) -> Self {
        let _ = (&m, at, &cx);
        itPickup {
            gr_light_offset: Quat::import(m, at + 0x0, cx),
            gr_heavy_offset: Quat::import(m, at + 0x10, cx),
            air_light_offset: Quat::import(m, at + 0x20, cx),
        }
    }

    fn compare(&self, m: &Mem, at: u32, path: &str, cx: &mut dyn Cx) {
        let _ = (&m, at, path, &cx);
        self.gr_light_offset
            .compare(m, at + 0x0, &format!("{path}.gr_light_offset"), cx);
        self.gr_heavy_offset
            .compare(m, at + 0x10, &format!("{path}.gr_heavy_offset"), cx);
        self.air_light_offset
            .compare(m, at + 0x20, &format!("{path}.air_light_offset"), cx);
    }
}

