impl Mirror for FtPartsVis {
    const SIZE: u32 = 0x20;

    fn import(m: &Mem, at: u32, cx: &mut dyn Cx) -> Self {
        let _ = (&m, at, &cx);
        FtPartsVis {
            model_num: m.u32(at + 0x0),
            cleared: core::array::from_fn(|i0| m.u8(at + 0x4 + i0 as u32 * 0x1)),
            xC: core::array::from_fn(|i0| cx.import_data(m.u32(at + 0xc + i0 as u32 * 0x4))),
        }
    }

    fn compare(&self, m: &Mem, at: u32, path: &str, cx: &mut dyn Cx) {
        let _ = (&m, at, path, &cx);
        if self.model_num != m.u32(at + 0x0) {
            cx.mismatch(
                &format!("{path}.model_num"),
                format!("{:?}", self.model_num),
                format!("{:?}", m.u32(at + 0x0)),
            );
        }
        for i0 in 0..5 {
            if self.cleared[i0] != m.u8(at + 0x4 + i0 as u32 * 0x1) {
                cx.mismatch(
                    &format!("{}[{}]", format!("{path}.cleared"), i0),
                    format!("{:?}", self.cleared[i0]),
                    format!("{:?}", m.u8(at + 0x4 + i0 as u32 * 0x1)),
                );
            }
        }
        for i0 in 0..5 {
            cx.compare_data(
                &format!("{}[{}]", format!("{path}.xC"), i0),
                self.xC[i0],
                m.u32(at + 0xc + i0 as u32 * 0x4),
            );
        }
    }
}

