                cx.mismatch(
                    &format!("{}[{}]", format!("{path}.triggers"), i0),
                    format!("{:?}", self.triggers[i0]),
                    format!("{:?}", f32::from_bits(m.u32(at + 0x30 + i0 as u32 * 0x4))),
                );
